import WebKit

/// Page scripts share the DOM with this world, but cannot call its handler or
/// read its capability. Only a trusted click on the reader's toolbar can post.
@MainActor
enum MarkdownRememberBridge {
    static let name = "qwaveRemember"
    static let world = WKContentWorld.world(name: "qwave-markdown-remember")
    static let header = "X-Qwave-Markdown-Document"
    static let maxSelectionCharacters = 200_000

    static func script(token: String) -> String {
        // The token is generated by UUID, never taken from document content.
        """
        (function () {
          const token = '\(token)';
          const toolbar = document.querySelector('.md-shell > .md-toolbar');
          if (!toolbar) return;
          toolbar.querySelectorAll('button[data-remember]').forEach(function (button) {
            button.addEventListener('click', function (event) {
              if (!event.isTrusted) return;
              const scope = button.getAttribute('data-remember');
              if (scope !== 'page' && scope !== 'selection') return;
              const text = scope === 'selection' && window.getSelection()
                ? window.getSelection().toString().slice(0, \(maxSelectionCharacters)) : '';
              window.webkit.messageHandlers.\(name).postMessage({token, scope, text});
            });
          });
        })();
        """
    }
}

@MainActor
struct MarkdownRememberDocument {
    let token = UUID().uuidString
    let url: URL
    let source: String
    var navigation: WKNavigation?
    var awaitingIntent = true
    var ready = false

    func owns(_ candidate: URL?) -> Bool {
        guard let candidate,
            var expected = URLComponents(url: url, resolvingAgainstBaseURL: false),
            var actual = URLComponents(url: candidate, resolvingAgainstBaseURL: false)
        else { return false }
        expected.fragment = nil
        actual.fragment = nil
        return expected == actual
    }

    func action(body: [String: Any]) -> QwaveInternalAction? {
        guard ready, body["token"] as? String == token,
            let scope = body["scope"] as? String, scope == "page" || scope == "selection"
        else { return nil }
        let selection = body["text"] as? String ?? ""
        guard selection.count <= MarkdownRememberBridge.maxSelectionCharacters else { return nil }
        // A page remember uses the native source, not a mutable DOM block or
        // a string supplied by page JavaScript.
        let text = scope == "selection" && !selection.isEmpty ? selection : source
        return .remember(scope: scope, text: text)
    }
}
